define([
  "jquery",
  "core/notification",
  "local_edzallcourse/subcourse",
], function ($, Notification, SubCourse) {
  const state = {
    filters: {},
    page: 1,
    perpage: 12,
    ajaxUrl: M.cfg.wwwroot + "/local/edzallcourse/ajax.php",
  };

  function collectFilters() {
    const filters = {};
    $("input.pc-filter-field[type=radio]:checked").each(function () {
      const field = $(this).data("field");
      const val = $(this).val();
      if (field) filters[field] = val;
    });
    state.filters = filters;
  }

  function fetchCatTree() {
    collectFilters();
    const payload = {
      filters: JSON.stringify(state.filters),
      page: state.page,
      perpage: state.perpage,
      sesskey: M.cfg.sesskey,
    };

    $.ajax({
      url: state.ajaxUrl,
      method: "POST",
      data: payload,
      dataType: "json",
    })
      .done(function (resp) {
        if (resp.template) {
          $("#pcattree-results").html(resp.template);
          const subcatId = $("#subcategory").val();
          if (subcatId) SubCourse.fetchCourses(subcatId);
        } else {
          $("#pcattree-results").html("<p></p>");
        }
      })
      .fail(function (err) {
        Notification.exception(err);
      });
  }

  function bindFilters() {
    $(document).on("change", "input.pc-filter-field[type=radio]", function () {
      state.page = 1; // reset to page 1 on filter change
      fetchCatTree();
    });
  }

  function bindPagination() {
    $(document).on("click", ".lc-page-btn", function () {
      state.page = parseInt($(this).data("page"), 10);
      fetchCatTree();
      $("html, body").animate(
        { scrollTop: $("#pcattree-results").offset().top - 80 },
        300,
      );
    });
  }

  function selectDefaultRadios() {
    const anyChecked = $("input.pc-filter-field[type=radio]:checked").length;
    if (!anyChecked) {
      $("input.pc-filter-field[type=radio]").first().prop("checked", true);
    }
  }

  function init() {
    bindFilters();
    bindPagination();
    selectDefaultRadios();
    fetchCatTree();
  }

  return { init: init };
});
